{"path": "_check.mjs", "content": "import assert from 'node:assert/strict';
import { mergeConfig } from './config.mjs';

// public tests
assert.deepEqual(mergeConfig({ mode: 'safe', retries: 3 }, { mode: 'fast' }), { mode: 'fast', retries: 3 });
assert.deepEqual(mergeConfig({ network: { host: 'localhost', port: 80 } }, { network: { port: 443 } }), { network: { host: 'localhost', port: 443 } });
assert.deepEqual(mergeConfig({ enabled: true, retries: 3 }, { enabled: false, retries: 0 }), { enabled: false, retries: 0 });

// TypeError cases
for (const bad of [null, undefined, [], 1, 'x', true]) {
  assert.throws(() => mergeConfig(bad, {}), TypeError);
  assert.throws(() => mergeConfig({}, bad), TypeError);
}
assert.throws(() => mergeConfig(), TypeError);

// default overrides = {}
assert.deepEqual(mergeConfig({ a: 1 }), { a: 1 });

// inherited keys ignored
const proto = { inherited: 'nope' };
const d = Object.create(proto); d.own = 1;
const o = Object.create(proto); o.own2 = 2;
assert.deepEqual(mergeConfig(d, o), { own: 1, own2: 2 });

// __proto__ from JSON.parse treated as data
const dp = JSON.parse('{"__proto__": {"x": 1}, "constructor": 5}');
const op = JSON.parse('{"__proto__": {"y": 2}}');
const r = mergeConfig(dp, op);
assert.equal(Object.getPrototypeOf(r), Object.prototype);
assert.deepEqual(Object.getOwnPropertyDescriptor(r, '__proto__').value, { x: 1, y: 2 });
assert.equal(r.constructor, 5);
assert.equal(Object.prototype.y, undefined);

// nested __proto__ key
const r2 = mergeConfig({ n: JSON.parse('{"__proto__": 1}') }, { n: { b: 2 } });
assert.deepEqual(Object.getOwnPropertyDescriptor(r2.n, '__proto__').value, 1);
assert.equal(r2.n.b, 2);

// no mutation / no retained references
const defaults = { net: { host: 'h', port: 80 }, list: { a: 1 } };
const overrides = { net: { port: 443 } };
const out = mergeConfig(defaults, overrides);
assert.deepEqual(defaults, { net: { host: 'h', port: 80 }, list: { a: 1 } });
assert.deepEqual(overrides, { net: { port: 443 } });
assert.notEqual(out.net, defaults.net);
assert.notEqual(out.net, overrides.net);
assert.notEqual(out.list, defaults.list);

// independence across repeated calls
const a = mergeConfig(defaults, overrides);
a.net.host = 'MUTATED';
a.list.a = 999;
const b = mergeConfig(defaults, overrides);
assert.deepEqual(b, { net: { host: 'h', port: 443 }, list: { a: 1 } });

// null / false / 0 replace nested
assert.deepEqual(mergeConfig({ n: { a: 1 } }, { n: null }), { n: null });
assert.deepEqual(mergeConfig({ n: { a: 1 } }, { n: false }), { n: false });
assert.deepEqual(mergeConfig({ n: { a: 1 } }, { n: 0 }), { n: 0 });
assert.deepEqual(mergeConfig({ n: null }, { n: { a: 1 } }), { n: { a: 1 } });

// nested merge preserves default fields
assert.deepEqual(mergeConfig({ n: { a: 1, b: 2 } }, { n: { b: 3, c: 4 } }), { n: { a: 1, b: 3, c: 4 } });

console.log('all checks passed');
"}

